1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Derives fiscal-year values from a date. The fiscal year starts on 1 July and is named after the
7	 * calendar year in which it ends, so a date from July onwards belongs to the fiscal year of the
8	 * following calendar year (e.g. 2026-08-10 is fiscal year 2027) while a date in January to June
9	 * belongs to the fiscal year of its own calendar year. Used for the owner's derived {@code
10	 * fiscalYear} label, the membership number's year segment and the elapsed-fiscal-year tenure, all
11	 * read from the business-day-adjusted registration date.
12	 */
13	public final class FiscalYear {
14	
15	    /** First month (1-based) of the fiscal year: July. */
16	    private static final int FISCAL_YEAR_START_MONTH = 7;
17	
18	    private FiscalYear() {
19	    }
20	
21	    /** Returns the fiscal year number containing {@code date}: the calendar year, plus one when the
22	     *  date falls on or after 1 July (the fiscal year is named after the year in which it ends). */
23	    public static int of(LocalDate date) {
24	        int year = date.getYear();
25	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? year + 1 : year;
26	    }
27	
28	    /** Returns the fiscal-year label for {@code date}, formatted 'FY<YY>' where YY is the last two
29	     *  digits of the fiscal year (e.g. 'FY27'). */
30	    public static String label(LocalDate date) {
31	        return String.format("FY%02d", of(date) % 100);
32	    }
33	
34	    /** Returns the number of whole fiscal years elapsed between {@code from} and {@code to}, i.e. the
35	     *  count of 1 July boundaries crossed. Zero (or negative) when both dates share a fiscal year. */
36	    public static int elapsed(LocalDate from, LocalDate to) {
37	        return of(to) - of(from);
38	    }
39	}
