1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Set;
4	
5	/**
6	 * Derives an owner's {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
7	 * {@code PREMIUM} when the membership level is 3 or more, otherwise {@code STANDARD}. AREA is
8	 * {@code METRO} when the locality is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
9	 * The four possible segments are {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
10	 * {@code STANDARD_METRO} and {@code STANDARD_REGIONAL}.
11	 */
12	public final class OwnerSegment {
13	
14	    /** The regions treated as METRO. */
15	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
16	
17	    private OwnerSegment() {
18	    }
19	
20	    /** The {@code '<TIER>_<AREA>'} segment for the given {@code membershipLevel} and {@code locality}. */
21	    public static String of(int membershipLevel, String locality) {
22	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
23	        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
24	        return tier + "_" + area;
25	    }
26	}
