1	package org.springframework.samples.petclinic.util;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Derives an owner's membership standing from a points score. Points start at 0 and accrue: +2 for a
7	 * usable email address, +1 when the owner has no namesakes, +2 for a household of three or more, and
8	 * +3 for a tenure of more than one elapsed fiscal year measured from the registration date. The points
9	 * are mapped to a membership level of 1 to 4: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or
10	 * more. Because a newly created owner has zero tenure, a new owner scores at most 5 points (level 3).
11	 */
12	public final class MembershipLevel {
13	
14	    private MembershipLevel() {
15	    }
16	
17	    /** Returns the membership points for an owner with the given {@code email}, {@code namesakeCount},
18	     *  {@code householdSize} and {@code registrationDate}, as at {@code today}. */
19	    public static int points(String email, Integer namesakeCount, Integer householdSize,
20	            LocalDate registrationDate, LocalDate today) {
21	        int points = 0;
22	        if (email != null && !email.isBlank()) {
23	            points += 2;
24	        }
25	        if (namesakeCount != null && namesakeCount == 0) {
26	            points += 1;
27	        }
28	        if (householdSize != null && householdSize >= 3) {
29	            points += 2;
30	        }
31	        if (registrationDate != null && today != null
32	            && FiscalYear.elapsed(registrationDate, today) > 1) {
33	            points += 3;
34	        }
35	        return points;
36	    }
37	
38	    /** Maps membership {@code points} to a level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
39	    public static int level(int points) {
40	        if (points >= 6) {
41	            return 4;
42	        }
43	        if (points >= 4) {
44	            return 3;
45	        }
46	        if (points >= 2) {
47	            return 2;
48	        }
49	        return 1;
50	    }
51	}
