1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	import java.util.Set;
5	import java.util.stream.Collectors;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.util.CustomerCode;
11	import org.springframework.samples.petclinic.util.Locality;
12	
13	/**
14	 * Assigns the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where REGION is the
15	 * region derived from the owner's postcode (falling back to the city table, see {@link Locality}) and
16	 * HASH8 is the first eight upper-case hex characters of SHA-256 over the {@code normalizedTelephone +
17	 * lastName} (e.g. 'NSW-1A2B3C4D'). There are no per-city sequence numbers: the identity is a pure
18	 * function of the owner's region and the telephone/last-name hash. Runs after the owner is built (so the
19	 * telephone is already normalized to E.164) and before it is saved, mutating the code in place via
20	 * {@code @Val} for the save/respond steps to persist and return.
21	 *
22	 * <p>When the computed code collides with an existing owner's {@code customerCode}, {@code '-<n>'} is
23	 * appended with the smallest {@code n} of 2 or more that makes it unique, and the de-duplicated code is
24	 * assigned (e.g. a second 'NSW-1A2B3C4D' becomes 'NSW-1A2B3C4D-2', a third 'NSW-1A2B3C4D-3').
25	 */
26	public class AssignCustomerCode {
27	
28	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
29	        String region = Locality.of(owner.getCity(), owner.getPostcode());
30	        String base = CustomerCode.of(region, owner.getTelephone(), owner.getLastName());
31	        Set<String> existing = ownerRepository.findAll().stream()
32	                .map(Owner::getCustomerCode)
33	                .filter(Objects::nonNull)
34	                .collect(Collectors.toSet());
35	        String code = base;
36	        for (int n = 2; existing.contains(code); n++) {
37	            code = base + "-" + n;
38	        }
39	        owner.setCustomerCode(code);
40	    }
41	}
