3	import java.time.LocalDate;
4	import java.util.concurrent.atomic.AtomicLong;
5	
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.util.FiscalYear;
12	import org.springframework.samples.petclinic.util.MembershipLevel;
13	
14	/**
15	 * Emits an audit line on successful create via the dedicated {@code AUDIT} logger, carrying the
16	 * newly-assigned owner id, the {@code customerCode}, the {@code registrationDate} and the derived
17	 * {@code membershipLevel} and {@code membershipNumber}. Runs after {@code SaveOwner} so the owner id
18	 * is populated.
19	 *
20	 * <p>Alongside the human-readable line it emits an immutable structured {@link OwnerCreatedEvent} as
21	 * JSON on the same logger, carrying a {@code seq} that increases monotonically across creates and the
22	 * owner's current primary identifier (the {@code customerCode} today; whatever replaces it later).
23	 */
24	public class AuditOwnerCreated {
25	
26	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
27	
28	    /** Monotonically increasing sequence across all owner-created events for this application. */
29	    private static final AtomicLong SEQ = new AtomicLong();
30	
31	    public void service(@Val Owner owner) {
32	        String membershipNumber = owner.getCustomerCode() + "-M"
33	            + String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100);
34	        int membershipLevel = MembershipLevel.level(MembershipLevel.points(owner.getEmail(),
35	            owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate(),
36	            LocalDate.now()));
37	        AUDIT.info("owner created id={} customerCode={} registrationDate={} "
38	                + "membershipLevel={} membershipNumber={}",
39	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
40	            membershipLevel, membershipNumber);
41	
42	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
43	            primaryIdentifier(owner), membershipLevel);
44	        AUDIT.info(event.toJson());
45	    }
46	
47	    /** The owner's current primary identifier. Today this is the {@code customerCode}; when the
48	     *  customerCode is unified into the memberId, return the memberId here instead. */
49	    private static String primaryIdentifier(Owner owner) {
50	        return owner.getCustomerCode();
51	    }
52	}
