1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Immutable structured audit event emitted on a successful owner create. Serialized to JSON and
5	 * published on the {@code AUDIT} logger alongside the human-readable audit line.
6	 *
7	 * <p>{@code identifier} carries the owner's <em>current primary identifier</em>. Today that is the
8	 * {@code customerCode}; when the customerCode is unified into the memberId the caller passes the
9	 * memberId here instead, without any change to this event's shape. The JSON field is named
10	 * {@code customerCode} to match the published contract.
11	 */
12	public record OwnerCreatedEvent(long seq, Integer ownerId, String identifier, int membershipLevel) {
13	
14	    private static final String EVENT = "OWNER_CREATED";
15	
16	    /** Renders the event as the canonical JSON object
17	     *  {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}. */
18	    public String toJson() {
19	        return "{"
20	            + "\"seq\":" + seq
21	            + ",\"ownerId\":" + ownerId
22	            + ",\"customerCode\":" + quote(identifier)
23	            + ",\"membershipLevel\":" + membershipLevel
24	            + ",\"event\":\"" + EVENT + "\""
25	            + "}";
26	    }
27	
28	    private static String quote(String value) {
29	        if (value == null) {
30	            return "null";
31	        }
32	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
33	        for (int i = 0; i < value.length(); i++) {
34	            char c = value.charAt(i);
35	            switch (c) {
36	                case '"' -> sb.append("\\\"");
37	                case '\\' -> sb.append("\\\\");
38	                case '\n' -> sb.append("\\n");
39	                case '\r' -> sb.append("\\r");
40	                case '\t' -> sb.append("\\t");
41	                default -> {
42	                    if (c < 0x20) {
43	                        sb.append(String.format("\\u%04x", (int) c));
44	                    } else {
45	                        sb.append(c);
46	                    }
47	                }
48	            }
49	        }
50	        return sb.append('"').toString();
51	    }
52	}
