1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	
10	/**
11	 * Derives an owner's {@code identityKey} — the single value all duplicate detection is expressed
12	 * through. The key is the lower-case SHA-256 hex of {@code normalizedTelephone + '|' + lowerEmail +
13	 * '|' + soundex(lastName)}: a full-key match with an existing owner is a duplicate (409); any
14	 * differing component (a different telephone, email, or a last name with a different soundex) is a
15	 * distinct identity that is allowed.
16	 *
17	 * <p>Not an OfficeFloor function class — a plain helper shared by the create-owner steps so the key
18	 * derived at the uniqueness check, the soft-match check, and the key returned in the response are all
19	 * computed the same way.
20	 */
21	public final class OwnerIdentity {
22	
23	    private OwnerIdentity() {
24	    }
25	
26	    /**
27	     * Assembles the identity key: the lower-case SHA-256 hex over
28	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. {@code telephone} is
29	     * expected in E.164 form; {@code email} is normalized here (trimmed, lower-cased) and a null/blank
30	     * value contributes an empty component; the last name contributes its {@link #soundex soundex}
31	     * code.
32	     */
33	    public static String key(String telephone, String email, String lastName) {
34	        String tel = telephone == null ? "" : telephone;
35	        String mail = normalizeEmail(email);
36	        mail = mail == null ? "" : mail;
37	        String sdx = soundex(lastName);
38	        return sha256hex(tel + "|" + mail + "|" + sdx);
39	    }
40	
41	    /**
42	     * American Soundex code for {@code name}: the retained first letter followed by three digits (zero
43	     * padded). Non-letters are ignored; consonants map to digits (b,f,p,v→1; c,g,j,k,q,s,x,z→2;
44	     * d,t→3; l→4; m,n→5; r→6) with adjacent equal codes collapsed, collapse preserved across
45	     * {@code h}/{@code w} and broken by a vowel. A null/blank name yields {@code "0000"}.
46	     */
47	    public static String soundex(String name) {
48	        String letters = name == null ? "" : name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
49	        if (letters.isEmpty()) {
50	            return "0000";
51	        }
52	        StringBuilder code = new StringBuilder();
53	        code.append(letters.charAt(0));
54	        char previous = soundexCode(letters.charAt(0));
55	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
56	            char c = letters.charAt(i);
57	            // 'h' and 'w' are transparent: keep the previous code so equal codes on either side collapse.
58	            if (c == 'H' || c == 'W') {
59	                continue;
60	            }
61	            char digit = soundexCode(c);
62	            if (digit != '0' && digit != previous) {
63	                code.append(digit);
64	            }
65	            // A vowel breaks the run so equal codes either side of it are coded twice; a consonant sets
66	            // the run so an immediately repeated code collapses.
67	            previous = isVowel(c) ? '0' : digit;
68	        }
69	        while (code.length() < 4) {
70	            code.append('0');
71	        }
72	        return code.toString();
73	    }
74	
75	    private static char soundexCode(char c) {
76	        switch (c) {
77	            case 'B': case 'F': case 'P': case 'V':
78	                return '1';
79	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
80	                return '2';
81	            case 'D': case 'T':
82	                return '3';
83	            case 'L':
84	                return '4';
85	            case 'M': case 'N':
86	                return '5';
87	            case 'R':
88	                return '6';
89	            default:
90	                return '0';
91	        }
92	    }
93	
94	    private static boolean isVowel(char c) {
95	        return c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y';
96	    }
97	
98	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
99	    private static String sha256hex(String value) {
100	        try {
101	            byte[] hash = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
102	            StringBuilder sb = new StringBuilder(hash.length * 2);
103	            for (byte b : hash) {
104	                sb.append(String.format("%02x", b));
105	            }
106	            return sb.toString();
107	        }
108	        catch (NoSuchAlgorithmException ex) {
109	            throw new IllegalStateException("SHA-256 not available", ex);
110	        }
111	    }
112	
113	    /** Best-effort E.164 for a stored telephone; falls back to the raw value when it cannot form E.164. */
114	    public static String toE164(String telephone) {
115	        try {
116	            return TelephoneE164.toE164(telephone);
117	        }
118	        catch (InvalidTelephoneException ex) {
119	            return telephone;
120	        }
121	    }
122	
123	    /** Trimmed, lower-cased email, or null when absent — matching {@link NormalizeOwnerEmail}. */
124	    public static String normalizeEmail(String email) {
125	        if (email == null || email.isBlank()) {
126	            return null;
127	        }
128	        return email.trim().toLowerCase(Locale.ROOT);
129	    }
130	
131	    /**
132	     * Stable, shared household id: the first 12 upper-hex chars of SHA-256 over the canonical last
133	     * name and the postcode ({@code normalizedLastName + '|' + postcode}), so every owner with the
134	     * same last name and postcode derives the same value automatically — the household is keyed on
135	     * (lastName, postcode) alone. A null postcode contributes an empty component.
136	     */
137	    public static String householdId(String lastName, String postcode) {
138	        String normalizedLastName = canonicalName(lastName);
139	        String pc = postcode == null ? "" : postcode;
140	        try {
141	            byte[] hash = MessageDigest.getInstance("SHA-256")
142	                    .digest((normalizedLastName + "|" + pc).getBytes(StandardCharsets.UTF_8));
143	            StringBuilder sb = new StringBuilder(12);
144	            for (int i = 0; i < 6; i++) {
145	                sb.append(String.format("%02X", hash[i]));
146	            }
147	            return sb.toString();
148	        }
149	        catch (NoSuchAlgorithmException ex) {
150	            throw new IllegalStateException("SHA-256 not available", ex);
151	        }
152	    }
153	
154	    /** Lower-cased, trimmed, with any run of whitespace collapsed to a single space. */
155	    private static String canonicalName(String value) {
156	        if (value == null) {
157	            return "";
158	        }
159	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
160	    }
161	}
