3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} (so the request telephone
11	 * is E.164 and the email lower-cased) and before {@link BuildOwner}. Rejects the request with
12	 * {@link DuplicateIdentityException} (handled as 409) when it collides with an existing owner.
13	 *
14	 * <p>Duplicate detection is expressed through the single {@code identityKey} = SHA-256 hex over
15	 * normalized telephone, lower-cased email and {@link OwnerIdentity#soundex soundex(lastName)}. The
16	 * request collides only when its <em>whole</em> identityKey equals an existing owner's: same telephone,
17	 * same email <em>and</em> a last name with the same soundex. A differing component — a distinct
18	 * telephone, email, or a last name with a different soundex — is a separate identity that is allowed.
19	 * In particular two owners with the same last name and postcode but different telephones are no longer
20	 * a hard duplicate here: they get distinct keys and are created (then recorded as a soft match by
21	 * {@link FlagPossibleDuplicate}). {@code sharesHousehold: true} still bypasses the check entirely.
22	 */
23	public class EnsureUniqueOwnerIdentity {
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
26	            throws DuplicateIdentityException {
27	        // A declared household member opts in with sharesHousehold=true and bypasses the whole
28	        // duplicate block, so it is created even though it shares an existing owner's household.
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return;
31	        }
32	        String identityKey =
33	                OwnerIdentity.key(request.getTelephone(), request.getEmail(), request.getLastName());
34	        for (Owner existing : ownerRepository.findAll()) {
35	            // A soft-deleted owner is no longer a live identity: skip it, so a duplicate that would
36	            // otherwise block is allowed when its only match has been deleted.
37	            if (Boolean.TRUE.equals(existing.getDeleted())) {
38	                continue;
39	            }
40	            // Duplicate only when the whole identityKey matches: same telephone, email AND soundex(lastName).
41	            String existingKey = OwnerIdentity.key(OwnerIdentity.toE164(existing.getTelephone()),
42	                    existing.getEmail(), existing.getLastName());
43	            if (identityKey.equals(existingKey)) {
44	                throw new DuplicateIdentityException(identityKey);
45	            }
46	        }
47	    }
48	}
