3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Builds and derives values from an owner's {@code customerCode}. The code is
9	 * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode/city
10	 * (see {@link Locality}) and HASH8 is the first eight upper-case hex characters of SHA-256 over
11	 * the {@code normalizedTelephone + lastName}. The {@code checkDigit} is a single Luhn check digit
12	 * computed over the decimal digits contained in the code (non-digit characters such as the '-'
13	 * separator or the hex letters are ignored), doubling every second digit from the right. This is
14	 * the standard Luhn algorithm restated over the code's digits.
15	 */
16	public final class CustomerCode {
17	
18	    private CustomerCode() {
19	    }
20	
21	    /** Assemble the {@code '<REGION>-<HASH8>'} code for the given region, telephone and last name. */
22	    public static String of(String region, String telephone, String lastName) {
23	        return region + "-" + hash8(telephone, lastName);
24	    }
25	
26	    /** First eight UPPER-case hex characters of SHA-256 over {@code (telephone + lastName)}. */
27	    public static String hash8(String telephone, String lastName) {
28	        String tel = telephone == null ? "" : telephone;
29	        String name = lastName == null ? "" : lastName;
30	        try {
31	            byte[] hash = MessageDigest.getInstance("SHA-256")
32	                .digest((tel + name).getBytes(StandardCharsets.UTF_8));
33	            StringBuilder sb = new StringBuilder(8);
34	            for (int i = 0; i < 4; i++) {
35	                sb.append(String.format("%02X", hash[i]));
36	            }
37	            return sb.toString();
38	        }
39	        catch (NoSuchAlgorithmException ex) {
40	            throw new IllegalStateException("SHA-256 not available", ex);
41	        }
42	    }
43	
44	    /** The REGION portion of a {@code '<REGION>-<HASH8>'} code. */
45	    public static String region(String code) {
46	        int dash = code.indexOf('-');
47	        return dash < 0 ? code : code.substring(0, dash);
